#if os(iOS) || os(tvOS)
  import Flutter
  import UIKit

  /// Answers `com.plezy/app_icon` on iOS, iPadOS and tvOS: switches the home-screen icon between
  /// the primary icon and the Supporter alternates.
  ///
  /// The alternates live in each Runner's AlternateAppIcons.xcassets (generated by
  /// scripts/codegen/generate_app_icons.py) as `AppIcon-<id>`, and the Runner targets compile
  /// every app icon in it as an alternate. Dart only sees the id, and `default` for the primary
  /// icon. Compiled into the iOS and tvOS Runners only; macOS has no alternate icons.
  final class AppIconPlugin: NSObject, FlutterPlugin {
    private static let defaultIcon = "default"
    private static let alternatePrefix = "AppIcon-"

    /// The alternate icon names the asset catalog compiler wrote into Info.plist.
    private static let alternateNames: Set<String> = {
      let info = Bundle.main.infoDictionary ?? [:]
      var names = Set<String>()
      for key in ["CFBundleIcons", "CFBundleIcons~ipad"] {
        let icons = info[key] as? [String: Any]
        let alternates = icons?["CFBundleAlternateIcons"] as? [String: Any] ?? [:]
        names.formUnion(alternates.keys)
      }
      return names
    }()

    static func register(with registrar: FlutterPluginRegistrar) {
      let channel = FlutterMethodChannel(
        name: "com.plezy/app_icon",
        binaryMessenger: registrar.messenger()
      )
      registrar.addMethodCallDelegate(AppIconPlugin(), channel: channel)
    }

    func handle(_ call: FlutterMethodCall, result: @escaping FlutterResult) {
      switch call.method {
      case "isSupported":
        result(Self.isSupported)
      case "getCurrent":
        result(Self.iconId(UIApplication.shared.alternateIconName))
      case "setIcon":
        setIcon((call.arguments as? [String: Any])?["id"] as? String, result: result)
      default:
        result(FlutterMethodNotImplemented)
      }
    }

    private static var isSupported: Bool {
      UIApplication.shared.supportsAlternateIcons && !alternateNames.isEmpty
    }

    private static func iconId(_ alternateName: String?) -> String {
      guard let alternateName else { return defaultIcon }
      return alternateName.hasPrefix(alternatePrefix)
        ? String(alternateName.dropFirst(alternatePrefix.count)) : alternateName
    }

    private func setIcon(_ id: String?, result: @escaping FlutterResult) {
      guard Self.isSupported else {
        result(FlutterError(code: "unsupported", message: "Alternate app icons are unavailable", details: nil))
        return
      }
      guard let id else {
        result(FlutterError(code: "unknown_icon", message: "Missing icon id", details: nil))
        return
      }
      let name = id == Self.defaultIcon ? nil : Self.alternatePrefix + id
      if let name, !Self.alternateNames.contains(name) {
        result(FlutterError(code: "unknown_icon", message: "No app icon with id \(id)", details: nil))
        return
      }
      // Re-applying the icon already showing would still raise the system alert.
      if UIApplication.shared.alternateIconName == name {
        result(nil)
        return
      }
      UIApplication.shared.setAlternateIconName(name) { error in
        DispatchQueue.main.async {
          if let error {
            result(FlutterError(code: "failed", message: error.localizedDescription, details: nil))
          } else {
            result(nil)
          }
        }
      }
    }
  }
#endif
